import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx')
ws=wb['Total Reserves']
# map header to col
header_to_col={ws.cell(1,c).value: c for c in range(3,ws.max_column+1)}
# list countries we have
countries=['Belarus','Georgia','Moldova','Ukraine','Uzbekistan','Czechia','Latvia','Lithuania','Slovakia']
# find headers containing country
for country in countries:
    col=None
    for h,c in header_to_col.items():
        if h and h.startswith(country):
            col=c
            break
    if col:
        val=ws.cell(18,col).value
        print(country, 'col',col, 'val', val)
    else:
        print(country, 'col not found')
